style.css:
@-moz-document domain("claude.ai") {
/* ============================= */
  /*      فونت WebYekan           */
  /* ============================= */
  @font-face {
    font-family: 'WebYekan';
    src: url('https://v1.fontapi.ir/css/Yekan') format('woff2');
    font-weight: 400;
    font-style: normal;
  }

  /* ============================= */
  /*      فونت فارسی              */
  /* ============================= */
  body, input, textarea, button {
    font-family: 'WebYekan', -apple-system, BlinkMacSystemFont, sans-serif !important;
  }

  /* ============================= */
  /*      RTL برای همه صفحه       */
  /* ============================= */
  body {
    direction: rtl !important;
  }

  /* محتوای اصلی */
  main, article {
    direction: rtl !important;
  }

  /* متن‌های پیام */
  p, div, span, h1, h2, h3, h4, h5, h6 {
    direction: rtl !important;
    text-align: right !important;
  }

  /* باکس ورودی */
  [contenteditable="true"], textarea {
    direction: rtl !important;
    text-align: right !important;
  }

  /* ============================= */
  /*      تم شب                    */
  /* ============================= */
  
  /* پس‌زمینه اصلی */
  html {
    background: #0d0d0d !important;
  }

  /* صفحه اصلی */
  body {
    background: #0d0d0d !important;
    color: #e8e8e8 !important;
  }

  /* هدر */
  header {
    background: #1a1a1a !important;
    border-bottom: 1px solid #2a2a2a !important;
  }

  /* سایدبار */
  aside, nav[aria-label] {
    background: #1a1a1a !important;
    border-right: 1px solid #2a2a2a !important;
  }

  /* منوی کناری */
  [class*="sidebar"] {
    background: #1a1a1a !important;
  }

  /* محتوای اصلی چت */
  main {
    background: #0d0d0d !important;
  }

  /* پیام‌ها */
  [data-test-render-count] {
    background: #1a1a1a !important;
  }

  /* باکس ورودی پیام */
  [contenteditable="true"] {
    background: #1a1a1a !important;
    color: #e8e8e8 !important;
    border: 1px solid #2a2a2a !important;
  }

  /* تکست‌اریا و اینپوت */
  textarea, input[type="text"] {
    background: #1a1a1a !important;
    color: #e8e8e8 !important;
    border: 1px solid #2a2a2a !important;
  }

  /* دکمه‌ها */
  button {
    background: #2a2a2a !important;
    color: #e8e8e8 !important;
    border: 1px solid #3a3a3a !important;
  }

  button:hover {
    background: #3a3a3a !important;
  }

  /* دکمه ارسال */
  button[aria-label*="Send"], button[type="submit"] {
    background: #8b5cf6 !important;
  }

  button[aria-label*="Send"]:hover {
    background: #7c3aed !important;
  }

  /* کدها - LTR بمونن */
  pre, code {
    background: #1a1a1a !important;
    border: 1px solid #2a2a2a !important;
    direction: ltr !important;
    text-align: left !important;
  }

  /* بلاک کد */
  pre code {
    background: transparent !important;
  }

  /* لینک‌ها */
  a {
    color: #8b5cf6 !important;
  }

  /* اسکرول‌بار */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    background: #0d0d0d;
  }

  ::-webkit-scrollbar-thumb {
    background: #3a3a3a;
    border-radius: 4px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #4a4a4a;
  }

  /* مودال */
  [role="dialog"] {
    background: #1a1a1a !important;
    border: 1px solid #2a2a2a !important;
    direction: ltr !important;
  }

  /* دکمه بستن مودال */
  [role="dialog"] button[aria-label*="Close"],
  [role="dialog"] button[aria-label*="close"],
  button[style*="position: fixed"] {
    left: 53px !important;
    right: auto !important;
    top: 30px !important;
  }

  /* منو */
  [role="menu"] {
    background: #1a1a1a !important;
    border: 1px solid #2a2a2a !important;
  }

  /* آیتم‌های منو */
  [role="menuitem"] {
    color: #e8e8e8 !important;
  }

  [role="menuitem"]:hover {
    background: #2a2a2a !important;
  }

  /* تولتیپ */
  [role="tooltip"] {
    background: #2a2a2a !important;
    color: #e8e8e8 !important;
    border: 1px solid #3a3a3a !important;
  } 

	.max-md\:absolute.h-full.max-md\:flex-1 {
      padding-left: 50px;
  }

	  .code-block__code {
      direction: ltr !important;
      text-align: left !important;
  }
}
